  display: grid;
  gap: var(--space-5);
  padding: clamp(1rem, 2.5vw, 1.5rem);
  border: 1px solid var(--colour-border);
  border-inline-start: 4px solid var(--colour-data-accent);
  border-radius: var(--radius-card);
  background: var(--colour-surface);
  box-shadow: var(--shadow-card);
}

.published-conflict-resolution__header {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  justify-content: space-between;
  gap: var(--space-3) var(--space-6);
}

.published-conflict-resolution__header h3 {
  max-width: 54rem;
  margin: var(--space-1) 0 0;
  font-size: clamp(1.25rem, 2.5vw, 1.6rem);
  line-height: 1.25;
}

.published-conflict-resolution__eyebrow {
