  color: var(--colour-text-secondary);
  font-size: 0.875rem;
  white-space: nowrap;
}

.published-conflict-resolution__summary {
  max-width: 65rem;
  margin: 0;
  color: var(--colour-text-secondary);
  line-height: 1.55;
}

.published-conflict-resolution__table-wrap {
  max-width: 100%;
