  border: 1px solid var(--colour-border);
  border-radius: var(--radius-card);
}

.published-conflict-resolution__table-wrap:focus-visible {
  outline: 3px solid var(--colour-focus);
  outline-offset: 3px;
}

.published-conflict-resolution__table {
  width: 100%;
  min-width: 32rem;
  border-collapse: collapse;
}

.published-conflict-resolution__table caption {
  padding: var(--space-3) var(--space-4);
