  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--colour-border);
  text-align: left;
  vertical-align: top;
}

.published-conflict-resolution__table thead th {
  background: var(--colour-surface-soft);
  font-size: 0.8125rem;
}

.published-conflict-resolution__table code {
  overflow-wrap: anywhere;
}

.published-conflict-resolution__decision {
  display: grid;
  gap: var(--space-3);
