}

.published-conflict-resolution__reason {
  display: grid;
  gap: var(--space-2);
  font-weight: 600;
}

.published-conflict-resolution__reason textarea {
  width: 100%;
  min-height: 6.5rem;
  resize: vertical;
  padding: var(--space-3);
  border: 1px solid var(--colour-border);
  border-radius: var(--radius-control);
  background: var(--colour-surface-soft);
  color: var(--colour-text);
  font: inherit;
  line-height: 1.45;
}

