                </button>
              ) : null}
            </>
          ) : (
            <ul>
              {resolution.candidates.map((candidate) => (
                <li key={candidate.candidateReference}>
                  <span>{candidate.label}</span>
                  <button
                    className="button button--secondary"
                    type="button"
                    disabled={saving}
                    onClick={() => {
                      setSaving(true);
                      setFeedback(null);
                      void mapBatchReference(client, batchReference, {
