              rowNumber: null,
              jsonPath: 'delivery',
              ordinal: 0,
            },
            context: {
              eventReference: 'cricsheet:delivery:fixture-1:0',
              fixtureId: '22',
              fixtureLabel: 'Lions vs Bears Â· 2026-09-01',
              inningsId: '31',
              overNumber: 1,
