+        <div>
+          <dt>Submitted items</dt>
+          <dd>{report.batch.progress.total}</dd>
+          <span>{report.batch.progress.processed} processed</span>
+        </div>
+        <div>
+          <dt>Unresolved references</dt>
+          <dd>{unresolved}</dd>
+          <span>includes informational issues</span>
